INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-orquesta-ritmica', 'La Orquesta Rítmica', 'Dinámica de percusión corporal, imitación vocal de instrumentos y coordinación rítmica colectiva en patrulla.', '<h2>📜 Descripción de La Orquesta Rítmica</h2>
<p><b>La Orquesta Rítmica</b> es una actividad escénica de percusión corporal, exploración sonora y coordinación rítmica colectiva. Diseñada para realizarse tanto en interiores como al aire libre durante un campamento, esta dinámica transforma a la patrulla o unidad scout en un ensamble musical vivo donde el cuerpo y la voz reemplazan a los instrumentos convencionales.</p>
<p>Cada patrulla asume el rol de una sección instrumental específica: los <i>''Tambores de Percusión''</i> (que generan ritmos base con pisadas en el suelo y golpeteos suaves en el pecho), los <i>''Vientos de Bronce''</i> (que imitan trompetas o trombones mediante zumbidos y modulaciones vocales), las <i>''Cuerdas''</i> (que realizan chasquidos de dedos y agudos) y los <i>''Bajos Vocales''</i> (que sostienen la armonía continua). Frente a la orquesta, un scout o dirigente actúa como Director de Orquesta, utilizando batuta y señas corporales para indicar qué sección entra en juego, aumentar o disminuir el volumen (crescendo y decrescendo) o detener el sonido en un silencio absoluto.</p>
<p>Esta actividad ejercita la agilidad auditiva, la modulación del tono muscular, la superación del temor escénico y la sincronización comunitaria en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega La Orquesta Rítmica?</h2>
<p>Para llevar a cabo la dinámica con dinamismo, ritmo y entusiasmo, los dirigentes y guías deben seguir estos pasos:</p>
<ul>
  <li><b>Asignación de Secciones Instrumentales:</b> Las patrullas se organizan en semicírculo frente al Director. A cada grupo se le asigna su familia de sonido (percusión corporal, vientos, cuerdas o bajos).</li>
  <li><b>Creación y Ensayo de Patrones Rítmicos:</b> Cada patrulla tiene 5 minutos para acordar y ensayar su patrón sonoro característico, asegurando que sea repetible y claro.</li>
  <li><b>Entrada en Escena del Director:</b> El Director se posiciona al centro y explica las claves de conducción: brazos extendidos hacia arriba significan aumento de volumen; palmas hacia abajo, susurro tenue; puño cerrado, silencio instantáneo.</li>
  <li><b>Ejecución de la Sinfonía Scout:</b> El Director señala consecutivamente a cada patrulla para que sume su ritmo a la mezcla, creando capas sonoras progresivas hasta alcanzar el clímax conjunto.</li>
  <li><b>Cierre Armónico y Aplauso:</b> Tras un remate perfecto de silencio conducido por el Director, la unidad completa estalla en un aplauso scout rítmico.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Orquesta Rítmica</h2>
<p>La actividad valora la precisión sonora, la escucha atenta y la creatividad en el Tally:</p>
<ul>
  <li><b>Mayor Sincronización Rítmica:</b> Otorgar 5 puntos a la patrulla que sostenga su compás sin acelerar ni desfasarse.</li>
  <li><b>Originalidad de Timbres Corporales:</b> Otorgar 3 puntos al equipo que invente los sonidos y efectos de voz más novedosos.</li>
  <li><b>Disciplinada Atención al Director:</b> Otorgar 3 puntos al grupo que responda con exactitud matemática a los matices de volumen y silencios.</li>
</ul>', '/uploads/la-orquesta-ritmica.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Estimular la creatividad", "Estimular la coordinación", "Trabajo en equipo", "Crear un ambiente de distensión"], "justificacion_areas": "La Orquesta Rítmica potencia la creatividad al requerir la invención y exploración de timbres musicales a través del propio cuerpo y la voz. Desarrolla la sociabilidad al enseñar la escucha activa, la sincronización en equipo y la armonía comunitaria desde Manada hasta Clan.", "variaciones": "<b>Orquesta de Sonidos de la Selva:</b> Imitar sonidos de aves, viento y animales del entorno natural.<br><b>Orquesta Muda por Señas:</b> Dirigir la orquesta utilizando únicamente lenguaje corporal de sombras.<br><b>Orquesta de Campamento Nocturno:</b> Realizar el ensamble sonoro alrededor de la fogata.", "recomendaciones": "Mantener una graduación limpia de volumen. Estimular la soltura de los beneficiarios más tímidos.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando en la creación de ritmos corporales e imitación de instrumentos."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Siguiendo con atención los matices y silencios indicados por el director."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Respondiendo con agilidad a las entradas y salidas de ritmo."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando armoniosamente con la seisena en el compás musical."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando patrones rítmicos de percusión en la patrulla."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo la escucha limpia y el respeto por las demás secciones."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la integración de timbres vocales y corporales."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo el ambiente festivo y ordenado en el taller rítmico."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando innovación sonora y métrica en la orquesta de Tropa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando disciplina y respeto por el compás colectivo."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Diseñando arreglos de percusión corporal para la patrulla."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y fraternidad del equipo rítmico."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo con la Avanzada la dirección y ensamble de composiciones sonoras."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Promoviendo el liderazgo integrador y la armonía comunitaria."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando el arte rítmico y la hermandad alegre en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo la fraternidad scout y la coordinación en proyectos compartidos."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

